#requires -Version 5.1
<# Base64 is encoding, not encryption. This companion runs the same readable script. Subtitle errors are non-blocking; video/audio completes first. #>
[CmdletBinding()]
param(
    [switch]$Gui,
    [switch]$NoPause,
    [string]$OutputDirectoryOverride,
    [string[]]$LinksOverride,
    [int]$QualityOverride = 0,
    [int]$ConcurrentFragmentsOverride = 0
)
$ErrorActionPreference = 'Stop'
$payload = @'

'@
$tempScript = Join-Path $env:TEMP ('yt-course-downloader-' + [Guid]::NewGuid().ToString('N') + '.ps1')
try {
    $bytes = [Convert]::FromBase64String(($payload -replace '\s',''))
    [IO.File]::WriteAllBytes($tempScript,$bytes)
    $forward = @{
        OutputDirectoryOverride = $(if($OutputDirectoryOverride){$OutputDirectoryOverride}else{$PSScriptRoot})
        CompanionSourceDirectoryOverride = $PSScriptRoot
        NoPause = $true
    }
    if($Gui){$forward.Gui=$true}
    if($LinksOverride -and $LinksOverride.Count -gt 0){$forward.LinksOverride=$LinksOverride}
    if($QualityOverride -ge 144){$forward.QualityOverride=$QualityOverride}
    if($ConcurrentFragmentsOverride -ge 1){$forward.ConcurrentFragmentsOverride=$ConcurrentFragmentsOverride}
    & $tempScript @forward
} catch {
    Write-Host ('Encoded wrapper error: '+$_.Exception.Message) -ForegroundColor Red
} finally {
    if(Test-Path -LiteralPath $tempScript){Remove-Item -LiteralPath $tempScript -Force -ErrorAction SilentlyContinue}
    if(-not $NoPause){Write-Host '';Read-Host 'Press Enter to close this window' | Out-Null}
}
